/** Display only the two ID shapes generated by our local fixture transports.
 * This is narrower than the public API's general job-ID syntax; it does not
 * change that contract or make an ID an authorization token. */
export function localDemoJobId(value: unknown): string | null {
  return typeof value === "string" && /^job_(?:[a-f0-9]{32}|[a-f0-9]{48})$/.test(value) ? value : null;
}
